import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class FixedCode {
    public static void main(String[] args) {
        // Establish a connection to the database
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "username", "password");

        // Create a prepared statement
        PreparedStatement pstmt = conn.prepareStatement("SELECT * FROM users WHERE name = ?");

        // Get user input
        String name = "John"; // Replace with user input

        // Use a try-with-resources statement to automatically close the resources
        try (PreparedStatement pstmt = conn.prepareStatement("SELECT * FROM users WHERE name = ?")) {
            pstmt.setString(1, name);

            // Execute the query
            ResultSet rs = pstmt.executeQuery();

            // Print the results
            while (rs.next()) {
                System.out.println(rs.getString("name"));
            }
        } catch (SQLException e) {
            System.out.println("Error executing query: " + e.getMessage());
        } finally {
            try {
                // Close the connection
                conn.close();
            } catch (SQLException e) {
                System.out.println("Error closing connection: " + e.getMessage());
            }
        }
    }
}
```

In the fixed code snippet, we use a try-with-resources statement to automatically close the resources, including the prepared statement and the connection. This ensures that the resources are properly closed, even if an exception is thrown. Additionally, we use a parameterized query to prevent SQL injection attacks.

